                renderer.setPixelRatio(window.devicePixelRatio || 1);
                renderer.setSize(w, h, false);
                controls.update();
                
                const aspect = w / h;
                const currentHeight = camera.top - camera.bottom;
                const currentCenterX = (camera.left + camera.right) / 2;
